#!/usr/bin/env python3
"""Embeds the smaller generated vectors in the hash-matrix host.

Run from the repository root after generate.py: python3 testdata/lzma/matrix_vectors.py
"""
import base64, os

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(os.path.dirname(HERE))
VECTORS = os.path.join(HERE, "vectors")
LIMIT = 12 * 1024

names = sorted(n for n in os.listdir(VECTORS) if os.path.getsize(os.path.join(VECTORS, n)) <= LIMIT)
out = os.path.join(ROOT, "tools", "hashmatrix", "Host", "Entries", "LzmaVectors.g.cs")
with open(out, "w", newline="\n") as f:
    f.write("// <auto-generated> by testdata/lzma/matrix_vectors.py from files written by the xz, lzip and 7-Zip tools.\n")
    f.write("// Do not edit; run the generator again.\n#nullable enable\nnamespace RecursiveAI.HashMatrix;\n\ninternal static class LzmaVectors\n{\n")
    f.write("    public static readonly (string Name, string Data)[] Files =\n    [\n")
    for n in names:
        with open(os.path.join(VECTORS, n), "rb") as v:
            f.write('        ("%s", "%s"),\n' % (n, base64.b64encode(v.read()).decode()))
    f.write("    ];\n}\n")
print(len(names), "vectors")
